enum AgentHookTemplates {
  static let pi = #"""
    // Generated by undoturn init. undoturn uninstall removes this file.
    import { spawn } from "node:child_process";

    const UNDOTURN = __UNDOTURN__;
    // The agent `undoturn init` installed this file for; it identifies the installation. Events name
    // the agent that loads the file instead (see the default export).
    const AGENT = __AGENT__;
    type Host = "pi" | "omp";
    const MUTATING_TOOLS: Record<Host, string[]> = __HOST_TOOLS__;

    type AgentMessage = {
      role?: string;
      provider?: string;
      model?: string;
      content?: string | Array<{ type?: string; text?: string }>;
    };
    type PromptEvent = { prompt?: string; messageType?: string };
    type ToolCallEvent = { toolName: string; input?: Record<string, unknown> };
    type AgentEndEvent = { messages: AgentMessage[]; willContinue?: boolean };
    type AgentSettledEvent = { aborted: boolean };
    type Context = {
      cwd: string;
      sessionManager: {
        getSessionId(): string;
        getSessionFile(): string | undefined;
      };
      model?: { provider: string; id: string };
    };
    type Handler<Event> = (event: Event, context: Context) => void | Promise<void>;
    interface ExtensionApi {
      /** Only Oh My Pi's API has this member: its package exports. */
      readonly pi?: unknown;
      on(event: "before_agent_start", handler: Handler<PromptEvent>): void;
      on(event: "tool_call", handler: Handler<ToolCallEvent>): void;
      on(event: "agent_end", handler: Handler<AgentEndEvent>): void;
      on(event: "agent_settled", handler: Handler<AgentSettledEvent>): void;
    }
    function report(message: unknown): void {
      process.stderr.write(`undoturn: ${String(message).replace(/[\r\n]+/g, " ")}\n`);
    }

    function modelName(model: Context["model"]): string | undefined {
      return model ? `${model.provider}/${model.id}` : undefined;
    }
    function lastAssistantModel(messages: AgentMessage[]): string | undefined {
      for (let index = messages.length - 1; index >= 0; index -= 1) {
        const message = messages[index];
        if (message.role !== "assistant") continue;
        if (typeof message.provider !== "string" || typeof message.model !== "string") {
          return undefined;
        }
        return `${message.provider}/${message.model}`;
      }
      return undefined;
    }

    function lastAssistantText(messages: AgentMessage[]): string | undefined {
      for (let index = messages.length - 1; index >= 0; index -= 1) {
        const message = messages[index];
        if (message.role !== "assistant") continue;
        if (typeof message.content === "string" && message.content.length > 0) return message.content;
        if (!Array.isArray(message.content)) continue;
        let text = "";
        for (const part of message.content) {
          if (part.type === "text" && typeof part.text === "string") text += part.text;
        }
        if (text.length > 0) return text;
      }
      return undefined;
    }

    function send(
      host: Host,
      payload: Record<string, unknown>,
    ): Promise<void> {
      // Pi waits for handlers without a deadline, so 60 seconds is UndoTurn's own bound. OMP
      // stops waiting after 30 seconds by default: stop the child first so the timeout is reported.
      const timeoutSeconds = host === "omp" ? 25 : 60;
      const { promise, resolve } = Promise.withResolvers<void>();
      let timer: NodeJS.Timeout | undefined;
      let finished = false;
      const finish = (message?: string) => {
        if (finished) return;
        finished = true;
        clearTimeout(timer);
        if (message) report(message);
        resolve();
      };

      let body: string | undefined;
      try {
        body = JSON.stringify(payload);
      } catch (error) {
        finish(`hook payload serialization failed: ${String(error)}`);
        return promise;
      }
      if (body === undefined) {
        finish("hook payload serialization failed");
        return promise;
      }

      try {
        const child = spawn(UNDOTURN, ["hook", host], { stdio: ["pipe", "ignore", "pipe"] });
        child.stderr?.resume();
        child.once("error", (error) => finish(`hook spawn failed: ${String(error)}`));
        child.stdin?.once("error", (error) => {
          child.kill();
          finish(`hook stdin failed: ${String(error)}`);
        });
        child.once("close", (code, signal) => {
          finish(code === 0 && signal === null
            ? undefined
            : `hook exited with ${signal ? `signal ${signal}` : `code ${code}`}`);
        });
        timer = setTimeout(() => {
          child.kill();
          finish(`hook timed out after ${timeoutSeconds} seconds`);
        }, timeoutSeconds * 1000);
        try {
          child.stdin?.end(body);
        } catch (error) {
          child.kill();
          finish(`hook stdin failed: ${String(error)}`);
        }
      } catch (error) {
        finish(`hook spawn failed: ${String(error)}`);
      }
      return promise;
    }

    export default function (api: ExtensionApi): void {
      // Oh My Pi can also load extensions installed for Pi, so the running agent comes from the API
      // shape rather than from AGENT.
      const host: Host = typeof api.pi === "object" && api.pi !== null ? "omp" : "pi";
      const tools = new Set(MUTATING_TOOLS[host]);
      const activeSessions = new Set<string>();
      const completedResponses = new Map<
        string,
        { model?: string; reply?: string; transcript?: string }
      >();
      api.on("before_agent_start", (event, ctx) => {
        if (typeof event.prompt !== "string" ||
            (event.messageType !== undefined && event.messageType !== "user")) return;
        const sessionID = ctx.sessionManager.getSessionId();
        activeSessions.add(sessionID);
        completedResponses.delete(sessionID);
        const model = modelName(ctx.model);
        return send(host, {
          hook_event_name: "UserPromptSubmit",
          session_id: sessionID,
          cwd: ctx.cwd,
          prompt: event.prompt,
          ...(model ? { model } : {}),
        });
      });

      api.on("tool_call", (event, ctx) => {
        if (!tools.has(event.toolName)) return;
        return send(host, {
          hook_event_name: "PreToolUse",
          session_id: ctx.sessionManager.getSessionId(),
          cwd: ctx.cwd,
          tool_name: event.toolName,
          ...(event.input !== undefined ? { tool_input: event.input } : {}),
        });
      });

      api.on("agent_end", (event, ctx) => {
        const sessionID = ctx.sessionManager.getSessionId();
        if (!activeSessions.has(sessionID)) return;
        const response = {
          model: lastAssistantModel(event.messages) ?? modelName(ctx.model),
          reply: lastAssistantText(event.messages),
          transcript: ctx.sessionManager.getSessionFile(),
        };
        // Oh My Pi has no agent_settled event; its agent_end says whether the run continues.
        if (host === "omp") {
          if (event.willContinue === true) return;
          activeSessions.delete(sessionID);
          return send(host, {
            hook_event_name: "Stop",
            session_id: sessionID,
            cwd: ctx.cwd,
            ...(response.model ? { model: response.model } : {}),
            ...(response.reply !== undefined ? { last_assistant_message: response.reply } : {}),
            ...(typeof response.transcript === "string" ? { transcript_path: response.transcript } : {}),
          });
        }
        completedResponses.set(sessionID, response);
      });

      if (host === "pi") {
        api.on("agent_settled", (_event, ctx) => {
          const sessionID = ctx.sessionManager.getSessionId();
          if (!activeSessions.has(sessionID)) return;
          const response = completedResponses.get(sessionID);
          const model = response?.model ?? modelName(ctx.model);
          const reply = response?.reply;
          const transcript = response?.transcript;
          activeSessions.delete(sessionID);
          completedResponses.delete(sessionID);
          return send(host, {
            hook_event_name: "Stop",
            session_id: sessionID,
            cwd: ctx.cwd,
            ...(model ? { model } : {}),
            ...(reply !== undefined ? { last_assistant_message: reply } : {}),
            ...(typeof transcript === "string" ? { transcript_path: transcript } : {}),
          });
        });
      }
    }
    """#

  static let omp = pi

  static let opencode = #"""
    // Generated by undoturn init. undoturn uninstall removes this file.
    import { spawn, spawnSync } from "node:child_process";

    const UNDOTURN = __UNDOTURN__;
    const AGENT = __AGENT__;
    const MUTATING_TOOLS = new Set(__TOOLS__);

    function report(message) {
      process.stderr.write(`undoturn: ${String(message).replace(/[\r\n]+/g, " ")}\n`);
    }

    function send(payload) {
      const { promise, resolve } = Promise.withResolvers();
      let timer;
      let finished = false;
      const finish = (message) => {
        if (finished) return;
        finished = true;
        clearTimeout(timer);
        if (message) report(message);
        resolve();
      };

      let body;
      try {
        body = JSON.stringify(payload);
      } catch (error) {
        finish(`hook payload serialization failed: ${String(error)}`);
        return promise;
      }
      if (body === undefined) {
        finish("hook payload serialization failed");
        return promise;
      }

      try {
        const child = spawn(UNDOTURN, ["hook", AGENT], { stdio: ["pipe", "ignore", "pipe"] });
        child.stderr?.resume();
        child.once("error", (error) => finish(`hook spawn failed: ${String(error)}`));
        child.stdin?.once("error", (error) => {
          child.kill();
          finish(`hook stdin failed: ${String(error)}`);
        });
        child.once("close", (code, signal) => {
          finish(code === 0 && signal === null
            ? undefined
            : `hook exited with ${signal ? `signal ${signal}` : `code ${code}`}`);
        });
        timer = setTimeout(() => {
          child.kill();
          finish("hook timed out after 60 seconds");
        }, 60000);
        try {
          child.stdin?.end(body);
        } catch (error) {
          child.kill();
          finish(`hook stdin failed: ${String(error)}`);
        }
      } catch (error) {
        finish(`hook spawn failed: ${String(error)}`);
      }
      return promise;
    }
    // OpenCode does not await event handlers before exit, so the final snapshot must finish inline.

    function sendSynchronously(payload) {
      let body;
      try {
        body = JSON.stringify(payload);
      } catch (error) {
        report(`hook payload serialization failed: ${String(error)}`);
        return;
      }
      if (body === undefined) {
        report("hook payload serialization failed");
        return;
      }

      let result;
      try {
        result = spawnSync(UNDOTURN, ["hook", AGENT], {
          input: body,
          stdio: ["pipe", "ignore", "pipe"],
          timeout: 60000,
        });
      } catch (error) {
        report(`hook spawn failed: ${String(error)}`);
        return;
      }
      if (result.error) {
        report(`hook spawn failed: ${String(result.error)}`);
      } else if (result.signal !== null) {
        report(`hook exited with signal ${result.signal}`);
      } else if (result.status !== 0) {
        report(`hook exited with code ${result.status}`);
      }
    }

    function reportSafely(handler) {
      return async (...args) => {
        try {
          await handler(...args);
        } catch (error) {
          report(`plugin handler failed: ${String(error)}`);
        }
      };
    }

    function modelName(model) {
      const provider = model?.providerID ?? model?.provider;
      const id = model?.modelID ?? model?.id;
      if (typeof provider === "string" && typeof id === "string") return `${provider}/${id}`;
      if (typeof id === "string") return id;
      return undefined;
    }

    function textFromParts(parts) {
      if (typeof parts === "string") return parts;
      if (!Array.isArray(parts)) return undefined;
      let text = "";
      for (const part of parts) {
        if (part?.type === "text" && typeof part.text === "string") text += part.text;
      }
      return text.length > 0 ? text : undefined;
    }


    export const UndoTurn = async ({ directory }) => {
      const activeSessions = new Set();
      const sessionModels = new Map();
      const replyParts = new Map();
      const completedResponses = new Map();

      return {
        "chat.message": reportSafely(async (input, output) => {
          const prompt = textFromParts(output?.parts ?? output?.message?.parts);
          const model = modelName(input.model);
          activeSessions.add(input.sessionID);
          sessionModels.delete(input.sessionID);
          completedResponses.delete(input.sessionID);
          replyParts.set(input.sessionID, new Map());
          if (model) sessionModels.set(input.sessionID, model);
          await send({
            hook_event_name: "UserPromptSubmit",
            session_id: input.sessionID,
            cwd: directory,
            ...(prompt !== undefined ? { prompt } : {}),
            ...(model ? { model } : {}),
          });
        }),

        "tool.execute.before": reportSafely(async (input, output) => {
          if (!MUTATING_TOOLS.has(input.tool)) return;
          await send({
            hook_event_name: "PreToolUse",
            session_id: input.sessionID,
            cwd: directory,
            tool_name: input.tool,
            tool_input: output.args,
          });
        }),

        event: reportSafely(({ event }) => {
          const properties = event?.properties;
          if (event?.type === "message.part.updated") {
            const part = properties?.part;
            const sessionID = properties?.sessionID;
            if (!activeSessions.has(sessionID) || part?.sessionID !== sessionID ||
                part.type !== "text" || typeof part.id !== "string" ||
                typeof part.messageID !== "string" || typeof part.text !== "string") return;
            const messages = replyParts.get(sessionID);
            if (!messages) return;
            let parts = messages.get(part.messageID);
            if (!parts) {
              parts = new Map();
              messages.set(part.messageID, parts);
            }
            parts.set(part.id, { text: part.text, start: part.time?.start });
            return;
          }
          if (event?.type === "message.updated") {
            const info = properties?.info;
            if (info?.role !== "assistant" || info.finish !== "stop" ||
                !Number.isFinite(info.time?.completed)) return;
            const sessionID = info.sessionID;
            if (typeof sessionID !== "string" || !activeSessions.has(sessionID)) return;
            const parts = typeof info.id === "string"
              ? replyParts.get(sessionID)?.get(info.id)
              : undefined;
            const reply = parts
              ? [...parts.values()]
                  .sort((left, right) => (left.start ?? 0) - (right.start ?? 0))
                  .map((part) => part.text)
                  .join("")
              : undefined;
            completedResponses.set(sessionID, {
              model: modelName(info) ?? sessionModels.get(sessionID),
              reply,
            });
            return;
          }
          if (event?.type !== "session.idle") return;
          const sessionID = properties?.sessionID;
          if (typeof sessionID !== "string" || !activeSessions.delete(sessionID)) return;
          const response = completedResponses.get(sessionID);
          const model = response?.model ?? sessionModels.get(sessionID);
          sessionModels.delete(sessionID);
          completedResponses.delete(sessionID);
          replyParts.delete(sessionID);
          sendSynchronously({
            hook_event_name: "Stop",
            session_id: sessionID,
            cwd: directory,
            ...(model ? { model } : {}),
            ...(response?.reply !== undefined ? { last_assistant_message: response.reply } : {}),
          });
        }),
      };
    };
    """#
}
